package nl.smartstreamlabs.sbwdroneconfig;
import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.resources.ResourceLocation;
/** One hull batch, one shared off-world payload pose per supported type; no payload entities in the level. */
public final class Ndc01Renderer extends EntityRenderer<Ndc01Entity>{private Id01Entity idPose;private CubedFpvDroneEntity fpvPose;public Ndc01Renderer(EntityRendererProvider.Context c){super(c);shadowRadius=2.1f;}@Override public ResourceLocation getTextureLocation(Ndc01Entity e){return ResourceLocation.tryParse("sbwdroneconfig:ndc01/carrier.png");}
 @Override public void render(Ndc01Entity e,float yaw,float partial,PoseStack p,MultiBufferSource buffers,int light){var origin=e.getPosition(partial);var m=Ndc01Geometry.frame(e,partial);m.m30(m.m30()-origin.x);m.m31(m.m31()-origin.y);m.m32(m.m32()-origin.z);p.pushPose();p.last().pose().mul(new org.joml.Matrix4f(m));p.last().normal().mul(new org.joml.Matrix3f(new org.joml.Matrix4f(m)));Ndc01Model.get().draw(e,partial,p,buffers,light,OverlayTexture.NO_OVERLAY);int slot=e.bay();if(slot>=0&&e.busy()&&e.hatchTime(slot,partial)>.25&&!e.cargo(slot).isEmpty()){var at=Ndc01Geometry.MODEL.payload[slot];p.pushPose();p.translate(at.x,at.y,at.z);net.minecraft.world.entity.Entity pose;if(e.cargo(slot).getItem()==AddonItems.ID01.get()){if(idPose==null||idPose.level()!=e.level())idPose=AddonEntities.ID01.get().create(e.level());pose=idPose;p.scale(.23f,.23f,.23f);}else{if(fpvPose==null||fpvPose.level()!=e.level())fpvPose=AddonEntities.CUBED_FPV_DRONE.get().create(e.level());pose=fpvPose;p.scale(.85f,.85f,.85f);}if(pose!=null){pose.tickCount=e.tickCount;pose.getPersistentData().putBoolean("sbwdroneconfigDockPreview",true);net.minecraft.client.Minecraft.getInstance().getEntityRenderDispatcher().getRenderer(pose).render(pose,0,partial,p,buffers,light);}p.popPose();}p.popPose();}
}
